import React from 'react';
import { useSelector } from 'react-redux';
// 1. This is the corrected import for the modern 'uuid' library
import { v4 as uuidv4 } from 'uuid';
import PostCard from '../PostCard'; // Assuming your PostCard component renders CardHeader

const Posts = () => {
    const { homePosts } = useSelector(state => state);

    return (
        <div className="posts">
            {
                homePosts.posts.map(post => (
                    // 2. The key should use the corrected function call: uuidv4()
                    <PostCard key={uuidv4()} post={post} />
                ))
            }
        </div>
    );
};

export default Posts;
